function editorModal(){let ed=st.editor;if(!ed)return '';return '<div class="po-overlay"><div class="po-drawer" role="dialog" aria-modal="true" aria-label="'+(ed.mode==='edit'?'Edit ':'New ')+esc(ed.role)+' record"><div class="po-drawer-head"><div><h2>'+(ed.mode==='edit'?'Edit':'Add')+' '+esc(ed.role.replace(/s$/,''))+'</h2><p>All required fields stay accessible regardless of column layout.</p></div>'+btn(icon('close',18),'ignore','po-secondary',false,'aria-label="Close editor"')+'</div><form data-action="save-form"><div class="po-drawer-body">'+roles[ed.role].map(f=>editorField(ed.role,f,ed.draft)).join('')+'</div><div class="po-drawer-foot">'+btn('Ignore','ignore','po-secondary')+'<button type="submit" class="po-button po-primary">Review changes</button></div></form></div></div>';}
function deleteModal(){let d=st.del;if(!d)return '';return '<div class="po-overlay"><div class="po-confirm" role="alertdialog" aria-label="Confirm archive"><h2>Archive '+esc(d.name)+'?</h2><p>This preserves record history. Linked active records must first be reassigned or archived; concurrent changes block the proposal.</p><div>'+btn('Cancel','cancel-delete','po-secondary')+btn('Review archive','review-delete','po-primary')+'</div></div></div>';}
function detailModal(){let d=st.details;if(!d)return '';let row=get(d.role,d.id);if(!row)return '';let extra=d.role==='projects'?'<div class="po-drawer-callout">'+btn('Add workstream','prefill:workstreams:'+row.id+':project','po-secondary',!can('workstreams'))+btn('Add milestone','prefill:milestones:'+row.id+':project','po-secondary',!can('milestones'))+'</div>':d.role==='milestones'?'<div class="po-drawer-callout">'+btn('Linked deliverable','prefill:deliverables:'+row.id+':milestone','po-secondary',!can('deliverables'))+'</div>':'';return '<div class="po-overlay"><div class="po-drawer" role="dialog" aria-modal="true" aria-label="Record detail"><div class="po-drawer-head"><div><h2>'+esc(row.data.name)+'</h2><p>Authorized record · version '+row.version+'</p></div>'+btn(icon('close',18),'close-detail','po-secondary',false,'aria-label="Close details"')+'</div><div class="po-detail-body">'+Object.entries(row.data).filter(([k])=>k!=='archived').map(([k,v])=>'<div class="po-detail-row"><span>'+esc(k.replace(/_/g,' '))+'</span><strong>'+esc(format(d.role,k,v))+'</strong></div>').join('')+extra+'</div><div class="po-drawer-foot">'+btn('Close','close-detail','po-secondary')+btn('Edit','edit:'+d.role+':'+row.id,'po-primary',!can(d.role))+'</div></div></div>';}
const views={overview,projects:projectsScreen,timeline:timelineScreen,deliverables:deliverableScreen,risks:riskScreen,reports:reportScreen};
const html='<div class="po-shell"><aside class="po-sidebar"><div class="po-app-title"><span>PROJECT OVERSIGHT</span><strong>Delivery command center</strong></div><nav aria-label="App sections">'+ordered.map(id=>{let x=screens.find(s=>s[0]===id);return btn(icon(id)+'<span>'+esc(x[1])+'</span>','nav:'+id,'po-nav-item '+(st.route===id?'active':''),false,'aria-current="'+(st.route===id?'page':'false')+'"');}).join('')+'</nav><div class="po-sidebar-end"><span class="po-indicator"></span>Internal company workspace<br><small>Access controlled by platform</small></div></aside><main class="po-main"><div class="po-topbar"><span>'+esc(layout.heading||cfg.heading||'Project Oversight')+'</span><div>'+tag('Internal')+btn(icon('settings',18),'tracker:layout','po-settings',false,'aria-label="Layout settings"')+'</div></div><div class="po-content">'+(st.notice?'<div class="po-notice" role="status">'+esc(st.notice)+'</div>':'')+(views[st.route]||overview)()+'</div><footer class="po-footer">Company project coordination · reviewed changes only · internal operational use</footer></main></div>'+editorModal()+deleteModal()+detailModal();
const css=typeof PROJECT_CSS==='string'?PROJECT_CSS:'';
return {html,css,state:st};
